        return len(pattern) == len(filename) and all(p == f or p == '?' for p, f in zip(pattern, filename))

    def backtrack(index, pattern):
        if index == n:
            if sum(matches(pattern, filenames[i]) for i in range(m)) == m and \
               all(not matches(pattern, filenames[i]) for i in range(n) if i not in to_delete):
                return pattern
            return None

