            return backtrack(index + 1, pattern + filenames[index][i])

    for i in range(1, n + 1):
        if i not in to_delete:
            initial_pattern = '?' * (len(filenames[0]) - 1)
            if backtrack(i, initial_pattern):
                return 'Yes\n' + initial_pattern + '*'
